var mix = {
	methods: {
		submitPayment() {
			const orderId = location.pathname.startsWith('/payment/')
				? Number(location.pathname.replace('/payment/', '').replace('/', ''))
				: null
			this.postData('/api/payment/' + orderId, {
				name: this.name,
				number: this.number1,
				year: this.year,
				month: this.month,
				code: this.code
			}).then(function(response) {
				var data = response.data || response
				if (data && data.error) {
					alert('Ошибка оплаты: ' + data.error)
				} else {
					alert('Успешная оплата')
					location.assign('/')
				}
			}).catch(function() {
				console.warn('Ошибка при оплате')
			})
		},
		generateNumber() {
			var num = ''
			for (var i = 0; i < 7; i++) {
				num += Math.floor(Math.random() * 10).toString()
			}
			var lastDigits = [2, 4, 6, 8]
			num += lastDigits[Math.floor(Math.random() * 4)].toString()
			this.number1 = num
		}
	},
	mounted() {
		var params = new URLSearchParams(location.search)
		var type = params.get('type')
		var btn = document.getElementById('generateBtn')
		if (btn && type === 'someone') {
			btn.style.display = 'inline-block'
		}
	},
	data() {
		return {
			number1: '',
			month: '',
			year: '',
			name: '',
			code: ''
		}
	}
}